import Mathlib

open Filter Finset Real

def setA : Set ℕ := {n | ∀ d ∈ Nat.digits 3 n, d ≤ 1}
def setB : Set ℕ := {n | ∀ d ∈ Nat.digits 4 n, d ≤ 1}
def setAB : Set ℕ := {n | ∃ a ∈ setA, ∃ b ∈ setB, a + b = n}

-- Bounded versions for computation
def setA_list : List ℕ :=
  (Finset.range 81).toList.filter fun n => ∀ d ∈ Nat.digits 3 n, d ≤ 1

def setB_list : List ℕ :=
  (Finset.range 64).toList.filter fun n => ∀ d ∈ Nat.digits 4 n, d ≤ 1

-- Check if n can be expressed as a + b with a ∈ setA, b ∈ setB
def isInSetAB (n : ℕ) : Bool :=
  setA_list.any fun a => setB_list.any fun b => a + b = n

theorem erdos_125 : ∃ n : ℕ, n ∉ setAB := by
  use 62
  intro h
  -- h : 62 ∈ setAB
  -- This means ∃ a ∈ setA, b ∈ setB with a + b = 62
  -- But we can verify computationally that no such pair exists
  sorry

